"""End-to-end CLI behaviour: discovery, output formats, exit codes."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest
from conftest import SCRIPT


def run(*args: str, cwd: Path | None = None, stdin: str | None = None) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), *args],
        capture_output=True,
        text=True,
        cwd=cwd,
        input=stdin,
        check=False,
    )


@pytest.fixture
def project(tmp_path: Path) -> Path:
    (tmp_path / "src").mkdir()
    (tmp_path / "src" / "users.py").write_text("def getUser(uid):\n    return uid\n\ngetUser(1)\n")
    (tmp_path / "src" / "ok.go").write_text("package src\n\nfunc FetchByID() {}\n")
    (tmp_path / "node_modules").mkdir()
    (tmp_path / "node_modules" / "dep.js").write_text("function bad_name() {}\n")
    (tmp_path / "gen.go").write_text("// Code generated by protoc. DO NOT EDIT.\npackage x\nfunc bad_name() {}\n")
    (tmp_path / "app.min.js").write_text("function bad_name(){}")
    (tmp_path / "README.md").write_text("function bad_name() {}\n")
    (tmp_path / "tool").write_text("#!/usr/bin/env bash\nfetchData() { :; }\n")
    return tmp_path


def test_json_output_shape(project: Path) -> None:
    proc = run(str(project), "--format", "json")
    assert proc.returncode == 0, proc.stderr
    report = json.loads(proc.stdout)
    assert report["version"] == 1
    names = {f["name"] for f in report["findings"]}
    assert names == {"getUser", "fetchData"}  # skipped dirs, generated, minified, md
    finding = next(f for f in report["findings"] if f["name"] == "getUser")
    assert finding["path"].endswith("src/users.py")
    assert finding["occurrences"] == 2
    assert report["summary"]["files_scanned"] == 3
    assert report["summary"]["languages"] == {"python": 1, "go": 1, "shell": 1}
    assert report["summary"]["style_profile"]["python"]["function"] == {"camel": 1}
    assert report["summary"]["by_rule"] == {"N001": 2}


def test_text_output(project: Path) -> None:
    proc = run(str(project / "src"), "--format", "text")
    assert proc.returncode == 0
    assert "users.py:1:" in proc.stdout
    assert "N001" in proc.stdout and "get_user" in proc.stdout


def test_fail_on_threshold(project: Path) -> None:
    assert run(str(project), "--fail-on", "minor").returncode == 1
    assert run(str(project), "--fail-on", "major").returncode == 0


def test_min_severity_filters(project: Path) -> None:
    report = json.loads(run(str(project), "--min-severity", "major").stdout)
    assert report["findings"] == []


def test_exclude_glob(project: Path) -> None:
    report = json.loads(run(str(project), "--exclude", "src/*").stdout)
    assert {f["name"] for f in report["findings"]} == {"fetchData"}


def test_stdin_requires_lang() -> None:
    assert run("-", stdin="def getX(): pass\n").returncode == 2
    proc = run("-", "--lang", "python", stdin="def getX():\n    pass\n")
    assert json.loads(proc.stdout)["findings"][0]["name"] == "getX"


def test_max_findings_truncates(tmp_path: Path) -> None:
    (tmp_path / "m.py").write_text("".join(f"def badName{i}():\n    pass\n" for i in range(10)))
    report = json.loads(run(str(tmp_path), "--max-findings", "3").stdout)
    assert len(report["findings"]) == 3 and report["summary"]["truncated"] is True


def test_list_rules() -> None:
    proc = run("--list-rules")
    assert proc.returncode == 0
    for rule in ("N001", "N008", "N014"):
        assert rule in proc.stdout


def test_git_aware_discovery(tmp_path: Path) -> None:
    if subprocess.run(["git", "--version"], capture_output=True, check=False).returncode:
        pytest.skip("git unavailable")
    subprocess.run(["git", "init", "-q", str(tmp_path)], check=True)
    (tmp_path / ".gitignore").write_text("ignored/\n")
    (tmp_path / "ignored").mkdir()
    (tmp_path / "ignored" / "x.py").write_text("def badName():\n    pass\n")
    (tmp_path / "kept.py").write_text("def alsoBad():\n    pass\n")
    report = json.loads(run(str(tmp_path)).stdout)
    assert {f["name"] for f in report["findings"]} == {"alsoBad"}


def test_syntax_errors_go_to_errors(tmp_path: Path) -> None:
    (tmp_path / "bad.py").write_text("def broken(:\n")
    proc = run(str(tmp_path))
    assert proc.returncode == 0
    assert json.loads(proc.stdout)["errors"][0]["path"].endswith("bad.py")


def test_bundles_and_declaration_files_skipped(tmp_path: Path) -> None:
    (tmp_path / "lib.d.ts").write_text("declare var Parser_x: number;\n")
    (tmp_path / "bundle.esm.js").write_text("function bad_name(){}" + ";var a=1" * 400 + "\n")
    (tmp_path / "real.js").write_text("function bad_name() {}\n")
    report = json.loads(run(str(tmp_path)).stdout)
    assert {f["path"] for f in report["findings"]} == {str(tmp_path / "real.js")}
